INSERT INTO questions (id, content, difficulty, sub_category_id) VALUES
('b0000000-0000-0000-0013-000000000000', 'Docker란 무엇이며 어떤 문제를 해결하기 위해 등장했나요?', 'EASY', 'b0000000-0000-0000-0000-000000000013'),
('b0000000-0000-0000-0013-000000000001', '컨테이너(container)와 가상 머신(VM)의 차이는 무엇인가요?', 'EASY', 'b0000000-0000-0000-0000-000000000013'),
('b0000000-0000-0000-0013-000000000002', 'Docker 이미지(Image)와 컨테이너(Container)의 차이는?', 'EASY', 'b0000000-0000-0000-0000-000000000013'),
('b0000000-0000-0000-0013-000000000003', 'Dockerfile이란 무엇인가요?', 'EASY', 'b0000000-0000-0000-0000-000000000013'),
('b0000000-0000-0000-0013-000000000004', 'Docker Hub는 어떤 서비스인가요?', 'EASY', 'b0000000-0000-0000-0000-000000000013'),
('b0000000-0000-0000-0013-000000000005', 'docker run 명령어의 주요 옵션(-d, -p, -v 등)은 무엇인가요?', 'MEDIUM', 'b0000000-0000-0000-0000-000000000013'),
('b0000000-0000-0000-0013-000000000006', '이미지(Image)를 빌드(build)할 때 고려해야 할 최적화 사항은 무엇인가요?', 'MEDIUM', 'b0000000-0000-0000-0000-000000000013'),
('b0000000-0000-0000-0013-000000000007', '도커 컴포즈(Docker Compose)는 무엇이고 언제 사용하나요?', 'MEDIUM', 'b0000000-0000-0000-0000-000000000013'),
('b0000000-0000-0000-0013-000000000008', '여러 개의 컨테이너를 오케스트레이션하기 위해 어떤 도구를 사용해봤나요?', 'MEDIUM', 'b0000000-0000-0000-0000-000000000013'),
('b0000000-0000-0000-0013-000000000009', '도커에서 볼륨(Volume)은 무엇이며 왜 필요한가요?', 'EASY', 'b0000000-0000-0000-0000-000000000013'),
('b0000000-0000-0000-0013-00000000000A', 'Docker에서 네트워킹은 어떻게 구성되나요? (브리지 네트워크 등)', 'MEDIUM', 'b0000000-0000-0000-0000-000000000013'),
('b0000000-0000-0000-0013-00000000000B', '이미지 최적화를 위해 고려해야 할 사항은 무엇인가요?', 'MEDIUM', 'b0000000-0000-0000-0000-000000000013'),
('b0000000-0000-0000-0013-00000000000C', 'Docker 컨테이너 상태(예: exited, up)를 보는 명령은 무엇인가요?', 'EASY', 'b0000000-0000-0000-0000-000000000013'),
('b0000000-0000-0000-0013-00000000000D', 'docker ps와 docker images 명령의 차이는 무엇인가요?', 'EASY', 'b0000000-0000-0000-0000-000000000013'),
('b0000000-0000-0000-0013-00000000000E', '컨테이너에 들어가서 명령을 실행하려면 어떻게 하나요? (예: docker exec)', 'EASY', 'b0000000-0000-0000-0000-000000000013'),
('b0000000-0000-0000-0013-00000000000F', '컨테이너를 중지(stop)와 kill하는 것의 차이는 무엇인가요?', 'MEDIUM', 'b0000000-0000-0000-0000-000000000013'),
('b0000000-0000-0000-0013-000000000010', 'Docker Swarm은 무엇이며, Kubernetes와 비교하면 어떤가요?', 'HARD', 'b0000000-0000-0000-0000-000000000013'),
('b0000000-0000-0000-0013-000000000011', '쿠버네티스(Kubernetes)와 Docker는 어떤 관계인가요?', 'MEDIUM', 'b0000000-0000-0000-0000-000000000013'),
('b0000000-0000-0000-0013-000000000012', '컨테이너 오케스트레이션이 필요한 이유는 무엇인가요?', 'MEDIUM', 'b0000000-0000-0000-0000-000000000013'),
('b0000000-0000-0000-0013-000000000013', 'Docker에서 포트 포워딩(포트 바인딩)은 어떻게 하나요?', 'EASY', 'b0000000-0000-0000-0000-000000000013'),
('b0000000-0000-0000-0013-000000000014', 'docker run -d -p 80:80 nginx 명령이 의미하는 바를 설명하세요.', 'EASY', 'b0000000-0000-0000-0000-000000000013'),
('b0000000-0000-0000-0013-000000000015', '컨테이너 내 애플리케이션 로그를 확인하려면 어떻게 해야 하나요?', 'EASY', 'b0000000-0000-0000-0000-000000000013'),
('b0000000-0000-0000-0013-000000000016', '레지스트리(Registry)란 무엇이며, 프라이빗 레지스트리를 구축해 본 적 있나요?', 'MEDIUM', 'b0000000-0000-0000-0000-000000000013'),
('b0000000-0000-0000-0013-000000000017', '이미 실행 중인 컨테이너를 수정하려면 어떤 절차가 필요할까요?', 'HARD', 'b0000000-0000-0000-0000-000000000013'),
('b0000000-0000-0000-0013-000000000018', '하나의 호스트에서 컨테이너 간 네트워크 통신을 가능하게 하려면?', 'MEDIUM', 'b0000000-0000-0000-0000-000000000013'),
('b0000000-0000-0000-0013-000000000019', '이미지의 태그(tag)는 어떤 목적으로 사용되나요?', 'EASY', 'b0000000-0000-0000-0000-000000000013'),
('b0000000-0000-0000-0013-00000000001A', 'Docker 컨테이너의 자원 할당(CPU, 메모리 제한)은 어떻게 설정하나요?', 'MEDIUM', 'b0000000-0000-0000-0000-000000000013');
